package com.aiassistant.mobile;
import org.json.*;import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** OpenAI-compatible HTTP client with bounded, classified failover. */
public final class ApexAiClient {
 public interface Callback{void onSuccess(String answer,String route);void onFailure(String reason);}
 private final ApexKeyStore store;private final ExecutorService worker=Executors.newSingleThreadExecutor();
 ApexAiClient(ApexKeyStore s){store=s;}
 public void test(String id,Callback cb){worker.execute(()->{try{JSONObject c=store.config(id);String a=request(c,store.key(id),"Reply only OK.",true);cb.onSuccess(a,c.optString("label"));}catch(Exception e){cb.onFailure(clean(e.getMessage()));}});}
 public void ask(String prompt,Callback cb){worker.execute(()->{List<ApexKeyStore.Entry> all=store.list();if(all.isEmpty()){cb.onFailure("No AI key configured. Open Settings.");return;}String last="No available provider.";for(ApexKeyStore.Entry e:all){try{String answer=request(store.config(e.id),store.key(e.id),prompt,false);store.status(e.id,"OK • recently used");cb.onSuccess(answer,e.label);return;}catch(Exception x){last=clean(x.getMessage());store.status(e.id,"Unavailable • "+last);if(last.startsWith("Bad request")){cb.onFailure(last);return;}if(last.startsWith("Offline")){cb.onFailure(last);return;}}}cb.onFailure("All configured keys failed. Last error: "+last);});}
 private String request(JSONObject config,String key,String prompt,boolean shortTest)throws Exception{
 String endpoint=config.optString("endpoint"),model=config.optString("model");HttpURLConnection c=null;
 try{URL u=new URL(endpoint);if(!"https".equalsIgnoreCase(u.getProtocol())&&!u.getHost().equals("10.0.2.2"))throw new Exception("Use HTTPS for provider endpoints.");c=(HttpURLConnection)u.openConnection();c.setRequestMethod("POST");c.setConnectTimeout(12000);c.setReadTimeout(45000);c.setDoOutput(true);c.setRequestProperty("Authorization","Bearer "+key);c.setRequestProperty("Content-Type","application/json");JSONObject body=new JSONObject();body.put("model",model);JSONArray msgs=new JSONArray();msgs.put(new JSONObject().put("role","system").put("content","You are Apex, the user's AI assistant. Your name is always Apex regardless of underlying provider or model."));msgs.put(new JSONObject().put("role","user").put("content",prompt));body.put("messages",msgs);body.put("max_tokens",shortTest?12:1000);byte[] data=body.toString().getBytes("UTF-8");c.getOutputStream().write(data);int code=c.getResponseCode();InputStream stream=code>=200&&code<300?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[2048];int n;while((n=stream.read(b))!=-1)out.write(b,0,n);String response=out.toString("UTF-8");if(code>=200&&code<300){JSONObject json=new JSONObject(response);return json.getJSONArray("choices").getJSONObject(0).getJSONObject("message").optString("content","No response text.");}
 if(code==400)throw new Exception("Bad request (400): verify model and endpoint.");if(code==401||code==403)throw new Exception("Authentication rejected ("+code+").");if(code==429)throw new Exception("Rate limit/quota (429).");if(code>=500)throw new Exception("Provider server error ("+code+").");throw new Exception("Provider HTTP "+code+".");
 }catch(UnknownHostException|ConnectException e){throw new Exception("Offline: cannot reach provider.");}finally{if(c!=null)c.disconnect();}
 }
 private String clean(String s){if(s==null)return "Request failed.";return s.length()>180?s.substring(0,180):s;}
}
